mapper.update:
UPDATE public.land_plot
SET land_area = land_area - #{area}
WHERE id = #{landPlotId}

mapper.select:
SELECT lp.* FROM public.land_plot lp WHERE 1=1
AND lp.land_type = #{landType}
AND lp.land_name LIKE CONCAT('%', #{landName}, '%')
AND lp.create_time BETWEEN TO_TIMESTAMP(#{startTime}, 'YYYY-MM-DD HH24:MI:SS') AND TO_TIMESTAMP(#{endTime}, 'YYYY-MM-DD HH24:MI:SS')
AND lp.land_area BETWEEN CAST(#{beginArea} AS REAL) AND CAST(#{endArea} AS REAL)
AND lp.create_by = #{phoneNumber}
AND lp.measurement_method = #{measurementMethod}
AND lp.address LIKE CONCAT('%', #{address}, '%')
ORDER BY lp.create_time DESC
-- 如果存在，则使用limit和offset进行分页，否则直接返回全部数据
LIMIT #{size} OFFSET (#{current} - 1) * #{size}

SELECT COUNT(*) FROM public.land_plot lp WHERE 1=1
AND lp.land_type = #{landType}
AND lp.land_name LIKE CONCAT('%', #{landName}, '%')
AND lp.create_time BETWEEN TO_TIMESTAMP(#{startTime}, 'YYYY-MM-DD HH24:MI:SS') AND TO_TIMESTAMP(#{endTime}, 'YYYY-MM-DD HH24:MI:SS')
AND lp.land_area BETWEEN CAST(#{beginArea} AS REAL) AND CAST(#{endArea} AS REAL)
AND lp.create_by = #{phoneNumber}
AND lp.measurement_method = #{measurementMethod}
AND lp.address LIKE CONCAT('%', #{address}, '%')
